// Spieloberfläche: zeigt die Geschichte Absatz für Absatz, die Entscheidungen, Vignette, Leiste und Notizbuch.
// Mit der Werkstatt (werkstatt.js): Im Modus "Bearbeiten" lässt sich jeder Absatz und jede Entscheidung ändern,
// streichen oder ergänzen. Die Änderungen sind Vorschläge; sie werden beim Weiterspielen schon so angezeigt.
// ?test=1   spielt eine im Browser kompilierte Fassung mit allen Quelltext-Vorschlägen (Mechanik)
// ?ab=knoten  beginnt direkt an einer Passage (zum Ausprobieren; eigener Spielstand)
(() => {
  const PARAM = new URLSearchParams(location.search);
  const TEST = PARAM.get("test") === "1";
  const AB = PARAM.get("ab");
  const PROBE = TEST || !!AB;
  const SPEICHER = PROBE ? "yharnam-spielstand-probe" : "yharnam-spielstand-v1";
  const W = window.WERKSTATT;
  const $ = (id) => document.getElementById(id);
  const text = $("text");
  const wahl = $("wahl");
  let story = null;
  let notizen = [];
  let letzterPfad = "";
  let letzteWahl = "";
  let letztesBild = "";
  let gelesen = [];
  let vorher = null;
  // Zurück: Schnappschüsse vor jeder Entscheidung (Ink-Zustand, Textlänge, gedimmte Absätze).
  let verlauf = [];
  // Erklärungen zu jeder Entscheidung (web/entscheidungen.json, erzeugt beim Bauen); im Modus Bearbeiten sichtbar.
  let erklaerungen = null;

  // Gelesen-Markierung (Wunsch des Nutzers 2026-11-06): Absätze, die schon einmal angezeigt wurden, und
  // Entscheidungen, die schon einmal getroffen wurden, erscheinen grün. Eigener Speicher, den weder
  // „Neu beginnen“ noch ein neuer Charakter löscht. Erkannt wird der Originaltext (nicht die Werkstatt-Fassung).
  const GELESEN = "yharnam-gelesen-v1";
  const kennung = (s) => {
    let h = 0x811c9dc5;
    for (const z of String(s).replace(/\s+/g, " ").trim()) h = Math.imul(h ^ z.codePointAt(0), 16777619) >>> 0;
    return h.toString(36);
  };
  const gesehen = (() => {
    try {
      const d = JSON.parse(localStorage.getItem(GELESEN) ?? "null");
      return { a: new Set(d?.a ?? []), w: new Set(d?.w ?? []) };
    } catch {
      return { a: new Set(), w: new Set() };
    }
  })();
  const gesehenSpeichern = () => {
    try {
      localStorage.setItem(GELESEN, JSON.stringify({ a: [...gesehen.a], w: [...gesehen.w] }));
    } catch {
      /* ohne Speicher keine Markierung, das Spiel läuft trotzdem */
    }
  };
  const wahlKennung = (c) => kennung(`${String(c.sourcePath ?? letzterPfad).split(".")[0]}|${c.text}`);
  // Feste Absätze des Textes (ohne eingefügte Vorschläge, Kommentare und Werkzeuge), für Speichern und Zurück.
  const fluechtig = (el) => el.classList.contains("eingefuegt") || el.classList.contains("kommentar") || el.classList.contains("ws-werkzeug") || el.tagName === "TEXTAREA";
  const stabil = () => [...text.children].filter((el) => !fluechtig(el));
  function gelesenMarkieren() {
    for (const p of text.querySelectorAll("p[data-orig]")) if (gesehen.a.has(kennung(p.dataset.orig))) p.classList.add("gelesen");
  }
  const K = () => window.KLANG;
  // Ortskarten: Name des Ortes beim Betreten (Tag # bild: id), ein Zeichen, bis es echte Bilder gibt.
  const ORTE = {
    anreise: "Die Straße nach Yharnam", klinik_innen: "Iosefkas Klinik", traum: "Der Jägertraum", laterne: "Vor der Klinik",
    zentral_yharnam: "Zentral-Yharnam", gilbert: "Gilberts Fenster", haus_dunkel: "Das dunkle Haus", tueren: "Die Gasse der Räucherlampen",
    scheiterhaufen: "Der Platz am Scheiterhaufen", brunnenplatz: "Der Brunnenplatz", gasse: "Die Gasse unter den Dächern",
    daecher_eileen: "Die Dachbalken", bruecke: "Die große Brücke", unterstadt: "Die Unterstadt", kanal: "Die Kanalisation",
    kanal_schwein: "Die Kanalisation", graeber: "Die Gräber", grab_oedon: "Das Grab des Oedon", werkstatt: "Gehrmans Werkstatt",
  };

  const speichern = () => {
    try {
      const absaetze = stabil()
        .slice(-400)
        .map((el) => ({ tag: el.tagName, html: el.dataset.orig === undefined ? el.innerHTML : "", orig: el.dataset.orig, pfad: el.dataset.pfad, cls: el.className.replace(/\b(geaendert|gestrichen)\b/g, "").trim() }));
      const versatz = stabil().length - absaetze.length;
      const daten = { state: story.state.toJson(), notizen, gelesen, absaetze, versatz, stimmung: document.body.dataset.stimmung, pfad: letzterPfad, bild: letztesBild };
      try {
        localStorage.setItem(SPEICHER, JSON.stringify({ ...daten, verlauf: verlauf.slice(-12) }));
      } catch {
        localStorage.setItem(SPEICHER, JSON.stringify(daten));
      }
    } catch {
      /* Speichern ist Komfort; ohne Speicher läuft das Spiel trotzdem. */
    }
  };
  const laden = () => {
    try {
      return JSON.parse(localStorage.getItem(SPEICHER) ?? "null");
    } catch {
      return null;
    }
  };

  const wert = (name) => story.variablesState[name];

  // Leiste: Zahlen und Icons. Ändert sich ein Wert, leuchtet sein Icon kurz auf; Treffer und Heilung zeigt der Rand.
  function aufleuchten(id) {
    const el = $(id);
    if (!el) return;
    el.classList.remove("leuchtet");
    void el.offsetWidth;
    el.classList.add("leuchtet");
  }
  function leisteAktualisieren() {
    const jetzt = { einsicht: wert("einsicht"), ampulle: wert("ampulle"), leben: wert("leben") };
    $("h-einsicht").textContent = jetzt.einsicht;
    $("h-ampulle").textContent = jetzt.ampulle;
    $("w-einsicht").dataset.stufe = String(Math.min(4, jetzt.einsicht));
    $("w-ampulle").dataset.voll = String(jetzt.ampulle);
    const v = $("vignette");
    if (jetzt.leben <= 3 && jetzt.leben >= 1) v.dataset.leben = String(jetzt.leben);
    else delete v.dataset.leben;
    if (vorher) {
      if (jetzt.einsicht !== vorher.einsicht) aufleuchten("w-einsicht");
      if (jetzt.ampulle !== vorher.ampulle) aufleuchten("w-ampulle");
      if (jetzt.leben < vorher.leben && jetzt.leben > 0) {
        randBlitz("treffer");
        K()?.treffer();
      } else if (jetzt.leben > vorher.leben && jetzt.ampulle < vorher.ampulle) {
        randBlitz("heilung");
      }
    }
    K()?.leben(jetzt.leben);
    vorher = jetzt;
    neuMarkieren();
  }
  function randBlitz(art) {
    document.body.classList.remove("treffer", "heilung");
    void document.body.offsetWidth;
    document.body.classList.add(art);
    setTimeout(() => document.body.classList.remove(art), 900);
  }
  // Tod: Schwarzblende, kurzer Satz, dann wieder Licht (der Text darunter geht weiter).
  function ueberblende(satz) {
    const u = $("ueberblende");
    u.querySelector("p").textContent = satz;
    u.classList.remove("an");
    void u.offsetWidth;
    u.classList.add("an");
    setTimeout(() => u.classList.remove("an"), 3400);
  }
  function gelernt(id) {
    try {
      const liste = story.variablesState["gelernt"];
      if (!liste) return false;
      return [...liste.keys()].some((k) => {
        try {
          return JSON.parse(k).itemName === id;
        } catch {
          return String(k).endsWith(`.${id}`);
        }
      });
    } catch {
      return false;
    }
  }

  function absatz(zeile, tags, pfad) {
    const p = document.createElement("p");
    p.textContent = zeile;
    p.dataset.orig = zeile;
    if (pfad) p.dataset.pfad = pfad;
    for (const tag of tags) {
      const [schluessel, ...rest] = tag.split(":");
      const k = schluessel.trim();
      const v = rest.join(":").trim();
      if (k === "stil") p.classList.add(v);
      if (k === "anzeichen") {
        p.classList.add("anzeichen");
        if (gelernt(v)) p.classList.add("erkannt");
      }
      if (k === "tod") p.classList.add("tod");
      if (k === "gedaechtnis") p.classList.add("gedaechtnis");
      if (k === "stimmung") document.body.dataset.stimmung = v;
      if (k === "lore" && window.NOTIZBUCH[v] && !notizen.includes(v)) notizen.push(v);
      if (k === "bild") p.dataset.bild = v;
      if (["klang", "stimmung", "kampf", "tod", "bild"].includes(k)) K()?.tag(k, v);
    }
    return p;
  }
  function ortskarte(bild) {
    const name = ORTE[bild];
    if (!name || bild === letztesBild) return null;
    const ort = ORTE[letztesBild];
    letztesBild = bild;
    if (ort === name) return null;
    document.body.dataset.ort = bild;
    const d = document.createElement("div");
    d.className = "ortskarte";
    d.innerHTML = '<span class="zier" aria-hidden="true">✦</span><span class="ortsname"></span><span class="zier" aria-hidden="true">✦</span>';
    d.querySelector(".ortsname").textContent = name;
    return d;
  }

  function weiter() {
    let erster = null;
    while (story.canContinue) {
      const pfad = story.state.currentPathString || letzterPfad;
      const zeile = story.Continue().trim();
      const tags = story.currentTags ?? [];
      const p = absatz(zeile, tags, pfad);
      if (pfad) letzterPfad = pfad;
      if (!zeile) continue;
      const karte = p.dataset.bild && ortskarte(p.dataset.bild);
      if (karte) {
        text.appendChild(karte);
        erster ??= karte;
      }
      const k = kennung(zeile);
      if (gesehen.a.has(k)) p.classList.add("gelesen");
      else gesehen.a.add(k);
      text.appendChild(p);
      erster ??= p;
      if (p.classList.contains("tod")) ueberblende("Du erwachst.");
    }
    gesehenSpeichern();
    ueberarbeitungAnwenden();
    leisteAktualisieren();
    zeigeWahl();
    baumLink();
    if (erster) erster.scrollIntoView({ behavior: "smooth", block: "start" });
    speichern();
  }

  // ------------------------------------------------------------ Vorschläge anzeigen
  function vorschlaege() {
    const T = new Map();
    const weg = new Set();
    const ein = new Map();
    const wahlNeu = new Map();
    const wahlWeg = new Set();
    for (const a of W?.liste() ?? []) {
      if (a.art === "text") T.set(a.vorher, a);
      if (a.art === "loeschen") weg.add(a.vorher);
      if (a.art === "einfuegen") ein.set(a.nach, [...(ein.get(a.nach) ?? []), a]);
      if (a.art === "wahl") wahlNeu.set(a.vorher, a);
      if (a.art === "wahl-loeschen") wahlWeg.add(a.vorher);
    }
    return { T, weg, ein, wahlNeu, wahlWeg };
  }

  // Kommentare an Claude und seine Antworten als Sprechblasen unter der Stelle (Absatz oder Entscheidung).
  function kommentarBox(orig) {
    if (!W || !orig) return null;
    const eigene = W.liste().filter((a) => a.art === "notiz" && a.vorher === orig);
    const passt = (x) => x && (orig === x || orig.startsWith(x));
    const verlauf = (W.antworten?.() ?? []).filter((a) => passt(a.vorher) || passt(a.nachher));
    if (!eigene.length && !verlauf.length) return null;
    const box = document.createElement("div");
    box.className = "kommentar";
    const zeile = (wer, txt, cls) => {
      const z = document.createElement("p");
      z.className = cls;
      const w = document.createElement("span");
      w.className = "wer";
      w.textContent = wer;
      z.append(w, document.createTextNode(` ${txt}`));
      box.appendChild(z);
      return z;
    };
    for (const a of verlauf) {
      zeile("Du:", a.frage ?? "", "frage");
      zeile(`Claude${a.status ? ` (${a.status})` : ""}:`, a.antwort ?? "", "claude");
    }
    for (const a of eigene) {
      const z = zeile("💬 Du:", a.nachher ?? "", "frage offen");
      z.title = "Antippen zum Ändern oder Löschen";
      z.onclick = () => W.notizOeffnen({ passage: a.passage, vorher: orig, kontext: a.kontext }, a);
    }
    return box;
  }

  function ueberarbeitungAnwenden() {
    const { T, weg, ein } = vorschlaege();
    for (const e of text.querySelectorAll("p.eingefuegt, div.kommentar")) e.remove();
    for (const p of text.querySelectorAll("p[data-orig]")) {
      if (p.hidden) continue;
      const orig = p.dataset.orig;
      const t = T.get(orig);
      p.textContent = t ? t.nachher : orig;
      p.classList.toggle("geaendert", !!t);
      p.classList.toggle("gestrichen", weg.has(orig));
      let anker = p;
      for (const a of ein.get(orig) ?? []) {
        const n = document.createElement("p");
        n.className = `eingefuegt${p.classList.contains("alt") ? " alt" : ""}`;
        n.textContent = a.nachher;
        n.dataset.vorschlag = a.id;
        n.dataset.pfad = p.dataset.pfad ?? "";
        anker.after(n);
        anker = n;
      }
      const k = kommentarBox(orig);
      if (k) anker.after(k);
    }
  }

  // ------------------------------------------------------------ Bearbeiten
  const passageVon = async (el) => (W ? W.passageVonPfad(el?.dataset.pfad || letzterPfad) : null);
  const kontext = () => ({ letzteWahl: letzteWahl || undefined, leben: wert("leben"), ampulle: wert("ampulle"), einsicht: wert("einsicht"), testfassung: TEST || undefined });

  function werkzeugSchliessen() {
    for (const w of text.querySelectorAll(".ws-werkzeug, textarea.ws-editor")) w.remove();
    for (const p of text.querySelectorAll("p[hidden]")) p.hidden = false;
  }

  async function absatzBearbeiten(p) {
    if (!W) return;
    werkzeugSchliessen();
    const { knopf, sicherKnopf, autoHoehe } = W.hilfen;
    const eingefuegtId = p.dataset.vorschlag;
    const orig = p.dataset.orig;
    const vorhanden = eingefuegtId ? null : W.liste().find((a) => a.art === "text" && a.vorher === orig);
    const ta = autoHoehe(document.createElement("textarea"));
    ta.className = "ws-editor";
    ta.value = p.textContent;
    p.hidden = true;
    p.after(ta);
    const leiste = document.createElement("div");
    leiste.className = "ws-werkzeug";
    ta.after(leiste);
    ta.focus();
    const passage = await passageVon(p);
    const ort = async () => ({ pfad: p.dataset.pfad, ...((await W.finden(orig ?? "")) ?? {}) });

    const uebernehmen = async () => {
      const neu = ta.value.trim();
      if (eingefuegtId) {
        if (neu) W.aendern(eingefuegtId, { nachher: neu });
        else W.entfernen(eingefuegtId);
      } else if (neu === orig) {
        if (vorhanden) W.entfernen(vorhanden.id);
      } else if (!neu) {
        W.hinzufuegen({ art: "loeschen", passage, vorher: orig, ort: await ort(), kontext: kontext() });
      } else {
        W.hinzufuegen({ art: "text", passage, vorher: orig, nachher: neu, ort: await ort(), kontext: kontext() });
      }
      werkzeugSchliessen();
      ueberarbeitungAnwenden();
    };
    ta.addEventListener("keydown", (e) => {
      if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) uebernehmen();
      if (e.key === "Escape") werkzeugSchliessen();
    });
    leiste.append(knopf("Übernehmen", uebernehmen, "ws-haupt"));
    if (!eingefuegtId) {
      leiste.append(
        knopf("Absatz danach einfügen", async () => {
          const a = W.hinzufuegen({ art: "einfuegen", passage, nach: orig, nachher: "…", ort: await ort(), kontext: kontext() });
          werkzeugSchliessen();
          ueberarbeitungAnwenden();
          const n = text.querySelector(`p.eingefuegt[data-vorschlag="${a.id}"]`);
          if (n) absatzBearbeiten(n);
        }),
        p.classList.contains("gestrichen")
          ? knopf("Wieder aufnehmen", () => {
            const w = W.liste().find((a) => a.art === "loeschen" && a.vorher === orig);
            if (w) W.entfernen(w.id);
            werkzeugSchliessen();
            ueberarbeitungAnwenden();
          })
          : knopf("Streichen", async () => {
            W.hinzufuegen({ art: "loeschen", passage, vorher: orig, ort: await ort(), kontext: kontext() });
            werkzeugSchliessen();
            ueberarbeitungAnwenden();
          }),
      );
      if (vorhanden) leiste.append(sicherKnopf("Original zurück", "Wirklich?", () => {
        W.entfernen(vorhanden.id);
        werkzeugSchliessen();
        ueberarbeitungAnwenden();
      }));
    } else {
      leiste.append(knopf("Entfernen", () => {
        W.entfernen(eingefuegtId);
        werkzeugSchliessen();
        ueberarbeitungAnwenden();
      }));
    }
    leiste.append(
      knopf("💬 Kommentar an Claude", () => W.notizOeffnen({ passage, vorher: orig, kontext: kontext() })),
      knopf("Quelltext", () => W.quelltextOeffnen(passage)),
      knopf("Abbrechen", werkzeugSchliessen, "ws-leise"),
    );
  }

  text.addEventListener("click", (e) => {
    if (!W?.bearbeiten()) return;
    const p = e.target.closest("p");
    if (!p || p.hidden || (p.dataset.orig === undefined && !p.dataset.vorschlag)) return;
    absatzBearbeiten(p);
  });

  // ------------------------------------------------------------ Entscheidungen
  function zeigeWahl(ruhig = false) {
    wahl.innerHTML = "";
    if ($("knopf-zurueck")) $("knopf-zurueck").disabled = !verlauf.length;
    wahl.classList.toggle("ruhig", ruhig);
    if (story.currentChoices.length === 0) {
      const ende = document.createElement("p");
      ende.className = "zwischentitel";
      ende.textContent = "Kapitel zwei folgt.";
      wahl.appendChild(ende);
      const neu = document.createElement("button");
      neu.textContent = "Von vorn beginnen";
      neu.onclick = () => {
        try {
          localStorage.removeItem(SPEICHER);
        } catch {
          /* nichts zu löschen */
        }
        location.href = location.pathname;
      };
      wahl.appendChild(neu);
      wahlWerkzeuge();
      return;
    }
    const { wahlNeu, wahlWeg } = vorschlaege();
    story.currentChoices.forEach((c, i) => {
      const zeile = document.createElement("div");
      zeile.className = "wahlzeile";
      const b = document.createElement("button");
      const r = wahlNeu.get(c.text);
      b.textContent = r ? r.nachher : c.text;
      if (r) b.classList.add("geaendert");
      if (wahlWeg.has(c.text)) b.classList.add("gestrichen");
      const bw = W?.liste().find((a) => a.art === "bewertung" && a.vorher === c.text);
      if (bw) b.dataset.bewertung = bw.wert;
      if (gesehen.w.has(wahlKennung(c))) {
        b.classList.add("gelesen");
        b.title = "Diese Entscheidung hast du schon einmal getroffen";
      }
      b.onclick = () => waehlen(i);
      b.style.animationDelay = `${i * 60}ms`;
      zeile.appendChild(b);
      if (W) {
        const s = document.createElement("button");
        s.type = "button";
        s.className = "stift";
        s.title = "Diese Entscheidung bearbeiten";
        s.setAttribute("aria-label", `Entscheidung „${c.text}“ bearbeiten`);
        s.textContent = "✎";
        s.onclick = () => wahlBearbeiten(zeile, c.text);
        zeile.appendChild(s);
      }
      wahl.appendChild(zeile);
      const k = kommentarBox(c.text);
      if (k) wahl.appendChild(k);
    });
    if (W?.bearbeiten() && erklaerungen) {
      const e = erklaerBlock(story.currentChoices);
      if (e) wahl.appendChild(e);
    }
    wahlWerkzeuge();
  }

  // Block „Claude erklärt“: je Option Ziel, Veränderung, spätere Wirkung, Begründung (Wunsch des Nutzers 2026-11-06).
  function erklaerBlock(choices) {
    const box = document.createElement("div");
    box.className = "erklaerung";
    const kopf = document.createElement("p");
    kopf.className = "erkl-kopf";
    kopf.textContent = "Claude erklärt diese Entscheidung";
    box.appendChild(kopf);
    let gefunden = 0;
    for (const c of choices) {
      const knoten = String(c.sourcePath ?? letzterPfad).split(".")[0];
      const e = erklaerungen.find((x) => x.knoten === knoten && x.text === c.text) ?? erklaerungen.find((x) => x.text === c.text);
      if (!e) continue;
      gefunden++;
      const opt = document.createElement("div");
      opt.className = "erkl-option";
      const t = document.createElement("p");
      t.className = "erkl-text";
      t.textContent = `› ${c.text}`;
      opt.appendChild(t);
      const ul = document.createElement("ul");
      const punkt = (label, wert, cls) => {
        if (!wert) return;
        const li = document.createElement("li");
        if (cls) li.className = cls;
        const b = document.createElement("b");
        b.textContent = `${label} `;
        li.append(b, document.createTextNode(wert));
        ul.appendChild(li);
      };
      punkt("Warum:", e.warum ?? "Begründung folgt.", e.warum ? "" : "fehlt");
      punkt("Führt zu:", e.ziel);
      punkt("Verändert:", e.setzt.length ? e.setzt.join(", ") : "nichts Dauerhaftes");
      for (const s of e.spaeter) punkt("Wirkt später:", `${s.variable} → ${s.orte.join(", ")}`);
      if (e.ohneEcho?.length) punkt("Noch ohne Echo:", e.ohneEcho.join(", "), "fehlt");
      punkt("Nur wenn:", e.bedingung);
      opt.appendChild(ul);
      box.appendChild(opt);
    }
    return gefunden ? box : null;
  }

  // Eine Option bewerten (gut oder schlecht); erneutes Tippen auf dieselbe Bewertung nimmt sie zurück.
  function bewerten(passage, original, wert) {
    const alt = W.liste().find((a) => a.art === "bewertung" && a.vorher === original);
    if (alt && alt.wert === wert) W.entfernen(alt.id);
    else if (alt) W.aendern(alt.id, { wert, nachher: wert });
    else W.hinzufuegen({ art: "bewertung", passage, vorher: original, wert, nachher: wert, kontext: kontext() });
  }

  async function wahlBearbeiten(zeile, original) {
    const { knopf, el } = W.hilfen;
    const passage = await passageVon(null);
    const vorhanden = W.liste().find((a) => a.art === "wahl" && a.vorher === original);
    const gestrichen = W.liste().find((a) => a.art === "wahl-loeschen" && a.vorher === original);
    zeile.hidden = true;
    const box = el("div", "ws-werkzeug wahl-editor");
    const input = el("input", "ws-editor");
    input.value = vorhanden?.nachher ?? original;
    box.appendChild(input);
    const fertig = () => {
      box.remove();
      zeigeWahl(true);
    };
    box.append(
      knopf("Übernehmen", () => {
        const neu = input.value.trim();
        if (!neu || neu === original) {
          if (vorhanden) W.entfernen(vorhanden.id);
        } else W.hinzufuegen({ art: "wahl", passage, vorher: original, nachher: neu, kontext: kontext() });
        fertig();
      }, "ws-haupt"),
      gestrichen
        ? knopf("Wieder aufnehmen", () => {
          W.entfernen(gestrichen.id);
          fertig();
        })
        : knopf("Streichen", () => {
          W.hinzufuegen({ art: "wahl-loeschen", passage, vorher: original, kontext: kontext() });
          fertig();
        }),
      knopf("👍 Gut", () => {
        bewerten(passage, original, "gut");
        fertig();
      }),
      knopf("👎 Schlecht", () => {
        bewerten(passage, original, "schlecht");
        fertig();
      }),
      knopf("💬 Kommentar an Claude", () => W.notizOeffnen({ passage, vorher: original, kontext: kontext() })),
      knopf("Abbrechen", fertig, "ws-leise"),
    );
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") box.querySelector(".ws-haupt").click();
      if (e.key === "Escape") fertig();
    });
    zeile.after(box);
    input.focus();
  }

  // Im Bearbeiten-Modus unter den Entscheidungen: eigene Vorschläge und Werkzeuge für die Stelle.
  async function wahlWerkzeuge() {
    if (!W) return;
    const { knopf, el, autoHoehe } = W.hilfen;
    const passage = await passageVon(null);
    const box = el("div", "nur-bearbeiten wahl-extra");
    for (const a of W.liste().filter((x) => x.art === "wahl-neu" && x.passage === passage)) {
      const b = el("button", "vorschlag", `${a.text}  (dein Vorschlag${a.ziel ? ` → ${a.ziel}` : ""})`);
      b.type = "button";
      b.title = "Vorgeschlagene Entscheidung: zum Bearbeiten klicken";
      b.onclick = () => neueWahl(a);
      box.appendChild(b);
    }
    const leiste = el("div", "ws-werkzeug");
    leiste.append(
      knopf("+ Entscheidung vorschlagen", () => neueWahl()),
      knopf("💬 Kommentar zu dieser Passage", () => W.notizOeffnen({ passage, kontext: kontext() })),
      knopf("Quelltext dieser Stelle", () => W.quelltextOeffnen(passage)),
    );
    box.appendChild(leiste);
    wahl.appendChild(box);

    function neueWahl(vorhanden) {
      box.querySelector(".neue-wahl")?.remove();
      const f = el("div", "ws-werkzeug neue-wahl");
      const t = el("input", "ws-editor");
      t.placeholder = "Text der Entscheidung, z. B. „Gilbert nach seiner Heimat fragen“";
      t.value = vorhanden?.text ?? "";
      const folge = autoHoehe(el("textarea", "ws-editor"));
      folge.placeholder = "Was passiert dann? So ausführlich du willst.";
      folge.value = vorhanden?.folge ?? "";
      const ziel = el("input", "ws-editor");
      ziel.placeholder = "Wohin geht es danach? (Passage, z. B. k1_hub_b, oder frei beschrieben)";
      ziel.value = vorhanden?.ziel ?? "";
      ziel.setAttribute("list", "ws-passagen");
      W.quelle().then((q) => {
        if ($("ws-passagen")) return;
        const dl = el("datalist");
        dl.id = "ws-passagen";
        for (const k of Object.keys(q.knoten)) dl.appendChild(Object.assign(el("option"), { value: k }));
        document.body.appendChild(dl);
      });
      f.append(t, folge, ziel,
        knopf("Speichern", () => {
          if (!t.value.trim()) return f.remove();
          const werte = { art: "wahl-neu", passage, text: t.value.trim(), nachher: t.value.trim(), folge: folge.value.trim() || undefined, ziel: ziel.value.trim() || undefined, kontext: kontext() };
          if (vorhanden) W.aendern(vorhanden.id, werte);
          else W.hinzufuegen(werte);
          zeigeWahl(true);
        }, "ws-haupt"),
        ...(vorhanden ? [knopf("Entfernen", () => {
          W.entfernen(vorhanden.id);
          zeigeWahl(true);
        })] : []),
        knopf("Abbrechen", () => f.remove(), "ws-leise"),
      );
      leiste.before(f);
      t.focus();
    }
  }

  function waehlen(i) {
    werkzeugSchliessen();
    const kinder = stabil();
    const neuAlt = kinder.filter((el) => el.tagName === "P" && !el.classList.contains("alt"));
    verlauf.push({
      state: story.state.toJson(),
      anzahl: kinder.length,
      alt: neuAlt.map((p) => kinder.indexOf(p)),
      notizen: [...notizen],
      pfad: letzterPfad,
      bild: letztesBild,
      stimmung: document.body.dataset.stimmung,
      wahl: letzteWahl,
    });
    if (verlauf.length > 30) verlauf.shift();
    gesehen.w.add(wahlKennung(story.currentChoices[i]));
    gesehenSpeichern();
    for (const p of neuAlt) p.classList.add("alt");
    letzteWahl = story.currentChoices[i].text;
    // Wahl mit #fliesst: Der folgende Text setzt sie als Satz fort (Entscheidung des Nutzers 2026-11-04);
    // dann keine eigene Zeile mit der Wahl, nur ein leiser Absatzwechsel.
    const fliesst = (story.currentChoices[i].tags ?? []).includes("fliesst");
    if (!fliesst) {
      const gewaehlt = document.createElement("p");
      gewaehlt.className = "alt";
      const angezeigt = vorschlaege().wahlNeu.get(letzteWahl)?.nachher ?? letzteWahl;
      gewaehlt.innerHTML = "<em></em>";
      gewaehlt.firstChild.textContent = `› ${angezeigt}`;
      text.appendChild(gewaehlt);
    }
    text.appendChild(document.createElement("hr"));
    story.ChooseChoiceIndex(i);
    weiter();
  }

  // Eine Entscheidung zurück (Wunsch des Nutzers 2026-11-06). Gelesenes bleibt grün.
  function zurueck() {
    const s = verlauf.pop();
    if (!s) return;
    werkzeugSchliessen();
    story.state.LoadJson(s.state);
    for (let k = stabil(); k.length > s.anzahl; k = stabil()) k.at(-1).remove();
    const feste = stabil();
    for (const i of s.alt) feste[i]?.classList.remove("alt");
    notizen = s.notizen;
    letzterPfad = s.pfad;
    letztesBild = s.bild;
    letzteWahl = s.wahl;
    document.body.dataset.stimmung = s.stimmung;
    gelesenMarkieren();
    ueberarbeitungAnwenden();
    leisteAktualisieren();
    zeigeWahl(true);
    baumLink();
    speichern();
    wahl.scrollIntoView({ block: "end" });
  }

  // Link in den Erzählbaum, direkt zur aktuellen Passage.
  async function baumLink() {
    const a = $("link-baum");
    if (!a || !W) return;
    const basis = a.dataset.basis ?? (a.dataset.basis = a.getAttribute("href"));
    const id = await W.passageVonPfad(letzterPfad);
    a.href = id ? `${basis}#p=${encodeURIComponent(id)}` : basis;
    // Das ganze Buch: zur Sprungmarke des Knotens (oder Stitches) der aktuellen Stelle
    const b = $("link-buch-leiste");
    if (b) {
      const bBasis = b.dataset.basis ?? (b.dataset.basis = b.getAttribute("href"));
      const teile = (id ?? "").split(".");
      const marke = teile.length > 1 && /^[A-Za-z_]/.test(teile[1]) ? `${teile[0]}--${teile[1]}` : teile[0];
      b.href = marke ? `${bBasis}#${marke}` : bBasis;
    }
  }

  function zeigeSpiel() {
    $("titel").hidden = true;
    text.hidden = false;
    wahl.hidden = false;
    $("leiste").hidden = false;
  }

  // Bestätigung in der Seite selbst: erster Klick fragt nach, zweiter Klick löscht.
  function neuBeginnen(e) {
    const knopf = e?.currentTarget;
    if (knopf && !knopf.dataset.sicher) {
      knopf.dataset.sicher = "1";
      knopf.dataset.text = knopf.textContent;
      knopf.textContent = "Wirklich? Noch einmal klicken";
      setTimeout(() => {
        delete knopf.dataset.sicher;
        knopf.textContent = knopf.dataset.text;
      }, 4000);
      return;
    }
    try {
      localStorage.removeItem(SPEICHER);
    } catch {
      /* ohne Speicher gibt es nichts zu löschen */
    }
    location.reload();
  }

  // Notizbuch-Stufen: "var", "!var", "var>=2", "var==wert", verknüpft mit && und ||. Unbekannte Namen gelten als Knoten (Besuche).
  function groesse(name) {
    try {
      const v = story.variablesState[name];
      if (v !== undefined && v !== null) return typeof v === "object" && "count" in v ? v.count : v;
    } catch {
      /* kein Merker dieses Namens */
    }
    try {
      return story.state.VisitCountAtPathString(name);
    } catch {
      return 0;
    }
  }
  function bedingungGilt(ausdruck) {
    if (!ausdruck) return true;
    return ausdruck.split("||").some((oder) => oder.split("&&").every((teil) => {
      const m = teil.trim().match(/^(!)?([\w.]+)\s*(>=|<=|==|!=|>|<)?\s*(.*)$/);
      if (!m) return false;
      const [, nicht, name, op, rechts] = m;
      const v = groesse(name);
      let ok;
      if (!op) ok = !!v;
      else {
        const r = rechts.trim() === "" ? "" : Number.isNaN(Number(rechts)) ? rechts.trim() : Number(rechts);
        ok = { ">=": v >= r, "<=": v <= r, "==": v == r, "!=": v != r, ">": v > r, "<": v < r }[op];
      }
      return nicht ? !ok : ok;
    }));
  }

  // Notizbuch als Buch: Reiter Aufzeichnungen, Personen, Fragen der Nacht. Neues ist markiert, bis man es gesehen hat.
  let reiter = "lore";
  const eintragTexte = (id) => {
    const e = window.NOTIZBUCH[id];
    const stufen = Array.isArray(e) ? [["", e[1]]] : e.stufen;
    return { titel: Array.isArray(e) ? e[0] : e.titel, texte: stufen.filter(([b]) => bedingungGilt(b)).map(([, t]) => t) };
  };
  const schluesselFuer = (id) => `${id}:${eintragTexte(id).texte.length}`;
  const personen = () => (window.PERSONEN ?? []).filter((p) => bedingungGilt(p.wenn)).map((p) => ({ name: p.name, text: p.stufen.find(([b]) => bedingungGilt(b))?.[1] ?? "" }));
  const fragen = () => (window.FRAGEN ?? []).filter(([b]) => bedingungGilt(b)).map(([, t]) => t);
  function alleSchluessel() {
    if (!story) return [];
    return [...notizen.map(schluesselFuer), ...personen().map((p) => `p:${p.name}:${p.text.length}`), ...fragen().map((f) => `f:${f}`)];
  }
  function neuMarkieren() {
    const neu = alleSchluessel().some((k) => !gelesen.includes(k));
    $("nb-neu").hidden = !neu;
  }
  function notizbuchFuellen() {
    const box = $("notizen");
    box.innerHTML = "";
    for (const b of document.querySelectorAll("#notizbuch [data-reiter]")) b.setAttribute("aria-selected", String(b.dataset.reiter === reiter));
    const artikel = (titel, texte, schluessel) => {
      const a = document.createElement("article");
      if (!gelesen.includes(schluessel)) a.classList.add("neu");
      a.appendChild(document.createElement("h3")).textContent = titel;
      for (const t of texte) a.appendChild(document.createElement("p")).textContent = t;
      box.appendChild(a);
    };
    if (reiter === "lore") {
      if (!notizen.length) box.innerHTML = '<p class="leer">Noch leer. Yharnam wird es füllen.</p>';
      for (const id of notizen) {
        const { titel, texte } = eintragTexte(id);
        if (texte.length) artikel(titel, texte, schluesselFuer(id));
      }
    } else if (reiter === "personen") {
      const liste = personen();
      if (!liste.length) box.innerHTML = '<p class="leer">Noch niemand.</p>';
      for (const p of liste) artikel(p.name, [p.text], `p:${p.name}:${p.text.length}`);
    } else {
      const liste = fragen();
      const a = document.createElement("article");
      const ul = document.createElement("ul");
      ul.className = "fragen";
      for (const f of liste) {
        const li = document.createElement("li");
        li.textContent = f;
        if (!gelesen.includes(`f:${f}`)) li.classList.add("neu");
        ul.appendChild(li);
      }
      a.appendChild(ul);
      box.appendChild(a);
    }
  }
  function notizbuchZeigen() {
    reiter = "lore";
    notizbuchFuellen();
    $("notizbuch").showModal();
    K()?.notizbuch();
  }
  for (const b of document.querySelectorAll("#notizbuch [data-reiter]")) {
    b.addEventListener("click", () => {
      reiter = b.dataset.reiter;
      notizbuchFuellen();
    });
  }
  $("notizbuch").addEventListener("close", () => {
    gelesen = [...new Set([...gelesen, ...alleSchluessel()])];
    neuMarkieren();
    speichern();
  });

  // ------------------------------------------------------------ Geschichte laden (normal oder Testfassung)
  function skriptLaden(src) {
    return new Promise((ok, fehler) => {
      const s = document.createElement("script");
      s.src = src;
      s.onload = ok;
      s.onerror = () => fehler(new Error(`${src} fehlt`));
      document.head.appendChild(s);
    });
  }
  async function geschichte() {
    if (!TEST) return (await fetch("story.json")).text();
    await skriptLaden("ink-full.js");
    const { dateien, fehler } = await W.quellenMitAenderungen();
    const ink = Object.fromEntries(Object.entries(dateien).filter(([n]) => n.startsWith("story/")).map(([n, t]) => [n.slice(6), t]));
    const meldungen = [];
    const handler = (m, typ) => typ === 2 && meldungen.push(m);
    const options = new inkjs.CompilerOptions("main.ink", [], false, handler, new inkjs.JsonFileHandler(ink));
    let json = null;
    try {
      json = new inkjs.Compiler(ink["main.ink"], options).Compile()?.ToJson();
    } catch (e) {
      meldungen.push(String(e?.message ?? e));
    }
    const band = document.createElement("div");
    band.className = "ws-testband";
    const aenderungen = W.liste().filter((a) => a.art === "quelle").length;
    band.innerHTML = `Testfassung mit ${aenderungen} Quelltext-Vorschlägen${fehler.length ? ` (nicht anwendbar: ${fehler.join(", ")})` : ""} · <a href="${location.pathname}">zurück zum Original</a>`;
    document.body.prepend(band);
    if (!json || meldungen.length) {
      const e = new Error("Deine Quelltext-Änderungen kompilieren nicht");
      e.details = meldungen;
      throw e;
    }
    return json;
  }

  async function start() {
    const json = await geschichte();
    story = new inkjs.Story(json);
    document.body.dataset.stimmung = "ruhig";
    const gespeichert = laden();
    if (gespeichert) $("fortsetzen").hidden = false;

    const beginnen = (name) => {
      story.variablesState["name"] = name;
      zeigeSpiel();
      if (AB) {
        try {
          story.ChoosePathString(AB);
          letzterPfad = AB;
        } catch {
          W?.hinweis(`Die Passage ${AB} lässt sich nicht direkt anspringen; es geht von vorn los.`, "fehler");
        }
      }
      weiter();
    };
    $("namensform").addEventListener("submit", (e) => {
      e.preventDefault();
      if (gespeichert && $("warnung").hidden) {
        $("warnung").hidden = false;
        return;
      }
      const ton = e.submitter?.value;
      if (ton) {
        K()?.setzen(ton === "an");
        tonZeigen();
      }
      beginnen($("name").value.trim() || "Jäger");
    });
    $("fortsetzen").addEventListener("click", () => {
      story.state.LoadJson(gespeichert.state);
      notizen = gespeichert.notizen ?? [];
      gelesen = gespeichert.gelesen ?? [];
      letztesBild = gespeichert.bild ?? "";
      letzterPfad = gespeichert.pfad ?? "";
      document.body.dataset.stimmung = gespeichert.stimmung ?? "ruhig";
      for (const a of gespeichert.absaetze ?? []) {
        const el = document.createElement(a.tag === "HR" ? "hr" : a.tag === "DIV" ? "div" : "p");
        if (a.orig !== undefined) {
          el.textContent = a.orig;
          el.dataset.orig = a.orig;
          if (a.pfad) el.dataset.pfad = a.pfad;
        } else el.innerHTML = a.html;
        el.className = a.cls;
        text.appendChild(el);
      }
      const v = gespeichert.versatz ?? 0;
      verlauf = (gespeichert.verlauf ?? [])
        .map((s) => ({ ...s, anzahl: s.anzahl - v, alt: (s.alt ?? []).map((i) => i - v).filter((i) => i >= 0) }))
        .filter((s) => s.anzahl >= 0);
      gelesenMarkieren();
      ueberarbeitungAnwenden();
      zeigeSpiel();
      leisteAktualisieren();
      zeigeWahl();
      baumLink();
      wahl.scrollIntoView({ block: "end" });
    });
    $("knopf-notizbuch").addEventListener("click", notizbuchZeigen);
    $("knopf-zurueck")?.addEventListener("click", zurueck);
    const tonKnopf = $("knopf-ton");
    const tonZeigen = () => {
      const an = K()?.an() ?? false;
      tonKnopf.setAttribute("aria-pressed", String(an));
      tonKnopf.textContent = an ? "Ton an" : "Ton aus";
    };
    tonKnopf.addEventListener("click", () => {
      K()?.umschalten();
      tonZeigen();
    });
    tonZeigen();
    $("neu").addEventListener("click", neuBeginnen);
    // Probe ab einer Passage: ohne Titelbildschirm sofort hinein.
    if (AB) beginnen("Jäger");

    W?.beiAenderung(() => {
      if (!story || $("titel").hidden === false) return;
      ueberarbeitungAnwenden();
      if (!wahl.querySelector(".wahl-editor, .neue-wahl")) zeigeWahl(true);
    });
    try {
      fetch(new URL("entscheidungen.json", location.href), { cache: "no-store" })
        .then((r) => (r.ok ? r.json() : null))
        .then((e) => {
          erklaerungen = Array.isArray(e) ? e : null;
          if (erklaerungen && story && $("titel").hidden && W?.bearbeiten()) zeigeWahl(true);
        })
        .catch(() => {});
    } catch {
      /* ohne Netz keine Erklärungen */
    }
    W?.beiModus(() => {
      if (!$("titel").hidden) return;
      werkzeugSchliessen();
      zeigeWahl(true);
    });
  }

  start().catch((e) => {
    const box = document.createElement("div");
    box.style.cssText = "padding:2rem;max-width:44rem;margin:3rem auto";
    const p = document.createElement("p");
    p.textContent = `Die Geschichte konnte nicht geladen werden (${e.message}).`;
    box.appendChild(p);
    if (e.details?.length) {
      const pre = document.createElement("pre");
      pre.style.cssText = "white-space:pre-wrap;font-size:0.8rem;color:#e0b0a0";
      pre.textContent = e.details.join("\n");
      box.appendChild(pre);
      const hilfe = document.createElement("p");
      hilfe.innerHTML = 'Öffne die Werkstatt (unten rechts) und korrigiere den Quelltext, oder <a href="index.html">spiele das Original</a>.';
      box.appendChild(hilfe);
    }
    $("buehne").replaceChildren(box);
  });
})();

dateien.web/stil.css:
:root {
  color-scheme: dark;
  --grund: #0d0b0a;
  --papier: #d8cfc0;
  --blass: #8f8577;
  --blut: #8c1b1b;
  --gold: #b39662;
  --linie: #2b2520;
  --tint: rgba(0, 0, 0, 0);
}
* { box-sizing: border-box; }
[hidden] { display: none !important; }
html, body { margin: 0; background: var(--grund); color: var(--papier); }
body {
  font-family: "EB Garamond", Georgia, serif;
  font-size: 1.15rem;
  line-height: 1.7;
  min-height: 100vh;
  background-image: radial-gradient(ellipse at 50% 0%, var(--tint), transparent 70%);
  transition: background-color 2s ease;
}
body[data-stimmung="ruhig"] { --tint: rgba(120, 110, 90, 0.10); }
body[data-stimmung="schoen"] { --tint: rgba(170, 140, 90, 0.14); }
body[data-stimmung="spannung"] { --tint: rgba(90, 60, 50, 0.16); }
body[data-stimmung="kampf"] { --tint: rgba(120, 20, 20, 0.20); }
body[data-stimmung="grauen"] { --tint: rgba(60, 70, 90, 0.20); }

#vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 5;
  box-shadow: inset 0 0 0 0 transparent;
  transition: box-shadow 1.2s ease;
}
/* Fünf unsichtbare Leben: bei 3 leicht orange, bei 2 leicht rot, bei 1 schwarz. */
#vignette[data-leben="3"] { box-shadow: inset 0 0 18vmin 4vmin rgba(214, 120, 40, 0.35); }
#vignette[data-leben="2"] { box-shadow: inset 0 0 22vmin 6vmin rgba(170, 20, 20, 0.45); }
#vignette[data-leben="1"] { box-shadow: inset 0 0 28vmin 10vmin rgba(0, 0, 0, 0.92); animation: puls 2.4s ease-in-out infinite; }
@keyframes puls { 50% { box-shadow: inset 0 0 32vmin 13vmin rgba(0, 0, 0, 0.96); } }

#leiste {
  position: fixed; top: 0; left: 0; right: 0; z-index: 4;
  display: flex; gap: 0.9rem; align-items: center; flex-wrap: nowrap; white-space: nowrap;
  padding-block: calc(0.5rem + env(safe-area-inset-top, 0px)) 0.5rem;
  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px));
  font-size: 0.82rem; color: var(--blass);
  background: linear-gradient(var(--grund) 70%, transparent);
  font-family: "Cormorant Garamond", serif; letter-spacing: 0.04em;
}
#leiste b { color: var(--papier); font-weight: 600; }
#leiste button { margin-left: auto; padding: 0.3rem 0.7rem; font-size: 0.9rem; }

#buehne { max-width: 40rem; margin: 0 auto; padding-block: calc(3.6rem + env(safe-area-inset-top, 0px)) 6rem;
  padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }
#text p { scroll-margin-top: 3.5rem; }

#titel { text-align: center; padding-top: 12vh; }
#titel h1 { font-family: "Cormorant Garamond", serif; font-weight: 400; font-size: clamp(3rem, 12vw, 5.5rem); letter-spacing: 0.12em; margin: 0.2em 0 0; color: var(--papier); }
.vorspann, .untertitel { font-family: "Cormorant Garamond", serif; font-style: italic; color: var(--blass); margin: 0; }
.untertitel { font-size: 1.3rem; margin-bottom: 3rem; }
.hinweis { margin-top: 3rem; font-size: 0.8rem; color: #5d554b; }
.warnung { color: #d39a6a; font-style: italic; max-width: 22rem; margin: 0.5rem auto; }
.baum { margin-top: 2.5rem; font-size: 0.95rem; color: var(--blass); }
.baum a { color: var(--gold); }
#fortsetzen { margin-top: 1rem; }
#namensform { display: grid; gap: 0.8rem; justify-items: center; }
.tonwahl { display: flex; gap: 0.6rem; flex-wrap: wrap; justify-content: center; }
.tonwahl .zweit { opacity: 0.75; }
.tonhinweis { color: var(--blass); font-size: 0.8rem; }
#namensform label { font-style: italic; color: var(--blass); }
input {
  font: inherit; color: var(--papier); background: transparent; text-align: center;
  border: 0; border-bottom: 1px solid var(--linie); padding: 0.4rem; width: min(18rem, 100%);
}
input:focus { outline: none; border-color: var(--gold); }

button {
  font: inherit; font-family: "Cormorant Garamond", serif; font-size: 1.05rem; letter-spacing: 0.03em;
  color: var(--papier); background: transparent; border: 1px solid var(--linie);
  padding: 0.55rem 1.2rem; cursor: pointer; transition: border-color 0.3s, color 0.3s, background 0.3s;
}
button:hover, button:focus-visible { border-color: var(--gold); color: #fff; background: rgba(179, 150, 98, 0.06); outline: none; }
button.leise { border: 0; color: #6d6458; font-size: 0.85rem; }

#text p { margin: 0 0 1.1em; animation: auftauchen 0.9s ease both; }
@keyframes auftauchen { from { opacity: 0; transform: translateY(4px); } }
#text p.titel { font-family: "Cormorant Garamond", serif; text-align: center; letter-spacing: 0.25em; font-size: 1.4rem; margin: 2.5rem 0; color: var(--gold); }
#text p.anschlag { font-family: "Cormorant Garamond", serif; font-size: 1.15rem; letter-spacing: 0.02em; color: #c9bfae; text-align: center; border-top: 1px solid var(--linie); border-bottom: 1px solid var(--linie); padding: 0.6rem 0.4rem; }
#text p.tagebuch { font-family: "Cormorant Garamond", serif; font-style: italic; font-size: 1.2rem; color: #b8ad9c; border-left: 1px solid var(--linie); padding-left: 1rem; }
#text p.zwischentitel { font-family: "Cormorant Garamond", serif; letter-spacing: 0.2em; font-size: 0.95rem; color: var(--gold); margin-top: 2rem; }
#text p.bilanz { color: #c4baa9; }
#text p.anzeichen { font-style: italic; color: #e6d9c4; border-left: 2px solid var(--blut); padding-left: 0.9rem; }
#text p.tod { color: #9a8f80; font-style: italic; }
#text p.gedaechtnis { font-style: italic; color: #b9c2cf; }
#text p.alt { opacity: 0.55; }
#text hr { border: 0; text-align: center; margin: 2rem 0; }
#text hr::after { content: "❧"; color: var(--linie); font-size: 1.2rem; }

#wahl { display: grid; gap: 0.6rem; margin-top: 1.8rem; }
#wahl .wahlzeile { display: flex; gap: 0.4rem; }
#wahl .wahlzeile > button:first-child { flex: 1; text-align: left; padding: 0.75rem 1rem; animation: auftauchen 0.6s ease both; }
#wahl .wahlzeile > button:first-child::before { content: "› "; color: var(--blut); }
#wahl > button { text-align: left; padding: 0.75rem 1rem; }
#wahl.ruhig .wahlzeile > button:first-child { animation: none; }

/* Werkstatt im Spiel: im Modus "Bearbeiten" ist jeder Absatz und jede Entscheidung anklickbar. */
#leiste .werkzeugknopf { margin-left: 0; padding: 0.3rem 0.6rem; font-size: 0.85rem; text-decoration: none; color: var(--papier); border: 1px solid var(--linie); }
#leiste .werkzeugknopf:hover { border-color: var(--gold); }
#leiste #knopf-notizbuch { margin-left: auto; }
.stift { display: none; padding: 0 0.8rem !important; color: var(--blass); }
body.bearbeiten .stift { display: block; }
.nur-bearbeiten { display: none; }
body.bearbeiten .nur-bearbeiten { display: grid; gap: 0.5rem; }
body.bearbeiten #text p[data-orig], body.bearbeiten #text p.eingefuegt { cursor: text; border-radius: 2px; transition: background 0.2s, box-shadow 0.2s; }
body.bearbeiten #text p[data-orig]:hover, body.bearbeiten #text p.eingefuegt:hover { background: rgba(179, 150, 98, 0.07); box-shadow: -0.6rem 0 0 rgba(179, 150, 98, 0.07), 0.6rem 0 0 rgba(179, 150, 98, 0.07); }
body.bearbeiten #text p.geaendert, body.bearbeiten #wahl button.geaendert { box-shadow: inset 3px 0 0 #7fae86; padding-left: 0.6rem; }
body.bearbeiten #text p.eingefuegt { box-shadow: inset 3px 0 0 #7fae86; padding-left: 0.6rem; font-style: normal; }
body.bearbeiten #text p.gestrichen, body.bearbeiten #wahl button.gestrichen { text-decoration: line-through; text-decoration-color: rgba(194, 91, 79, 0.7); opacity: 0.5; }
body:not(.bearbeiten) #text p.gestrichen { display: none; }
#wahl .vorschlag { text-align: left; padding: 0.6rem 1rem; border-style: dashed; color: var(--blass); font-style: italic; }
.wahl-editor input, .neue-wahl input, .neue-wahl textarea { margin-bottom: 0.2rem; }
.wahl-extra .ws-werkzeug { margin-bottom: 0; }
#leiste .umbruch { display: none; }
@media (max-width: 520px) {
  #leiste { flex-wrap: wrap; row-gap: 0.4rem; column-gap: 0.6rem; }
  #leiste .umbruch { display: block; flex-basis: 100%; height: 0; }
  #leiste #knopf-notizbuch { margin-left: 0; }
  #leiste button, #leiste .werkzeugknopf { padding: 0.25rem 0.6rem; font-size: 0.85rem; }
  #buehne { padding-top: calc(5.6rem + env(safe-area-inset-top, 0px)); }
  #text p { scroll-margin-top: 5.6rem; }
  .ws-schwebe { padding: 0.35rem 0.7rem; font-size: 0.9rem; }
}
#titel .werkstatt-start { margin-top: 0.8rem; font-size: 0.95rem; color: var(--blass); }

dialog {
  max-width: 34rem; width: calc(100% - 2rem); max-height: 80vh;
  background: #13100e; color: var(--papier); border: 1px solid var(--linie); padding: 1.5rem;
}
dialog::backdrop { background: rgba(0, 0, 0, 0.7); }
dialog h2 { font-family: "Cormorant Garamond", serif; font-weight: 400; letter-spacing: 0.1em; margin-top: 0; color: var(--gold); }
#notizen article { border-top: 1px solid var(--linie); padding: 0.8rem 0; }
#notizen h3 { margin: 0 0 0.3rem; font-family: "Cormorant Garamond", serif; font-weight: 600; font-size: 1.1rem; }
#notizen p { margin: 0; font-size: 1rem; color: #bdb3a3; }
#notizen .leer { color: var(--blass); font-style: italic; }
dialog form { display: inline; }

/* ------------------------------------------------------------ Leiste mit Icons */
.unsichtbar { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
#leiste .wert { display: inline-flex; align-items: center; gap: 0.3rem; }
#leiste .wert svg { width: 1.15rem; height: 1.15rem; overflow: visible; }
#leiste .wert.leuchtet svg { animation: leuchten 1.1s ease; }
@keyframes leuchten { 30% { filter: drop-shadow(0 0 6px rgba(224, 194, 122, 0.95)); transform: scale(1.25); } }
#w-echos .echo { fill: #c9b27a; opacity: 0.9; } #w-echos .echo2 { fill: #c9b27a; opacity: 0.45; }
#w-einsicht .lid { fill: none; stroke: #b9c2cf; stroke-width: 1.4; }
#w-einsicht .iris { fill: #8fa4bf; transform-origin: 12px 12px; transform: scaleY(0.08); transition: transform 1.2s ease; }
#w-einsicht .pupille { fill: #0d0b0a; }
#w-einsicht[data-stufe="1"] .iris { transform: scaleY(0.35); }
#w-einsicht[data-stufe="2"] .iris { transform: scaleY(0.6); }
#w-einsicht[data-stufe="3"] .iris { transform: scaleY(0.85); }
#w-einsicht[data-stufe="4"] .iris { transform: scaleY(1); fill: #b9c9de; }
#w-ampulle .glas { fill: rgba(216, 207, 192, 0.06); stroke: #8f8577; stroke-width: 1.3; }
#w-ampulle .blut { fill: #8c1b1b; transform-origin: 12px 21px; transform: scaleY(0); transition: transform 0.8s ease; }
#w-ampulle[data-voll="1"] .blut { transform: scaleY(1); }
.marke { fill: none; stroke: #b39662; stroke-width: 1.4; } .marke-zeichen { fill: none; stroke: #b39662; stroke-width: 1.4; stroke-linecap: round; }
#knopf-notizbuch { position: relative; }
.neu-punkt { position: absolute; top: -0.25rem; right: -0.25rem; width: 0.55rem; height: 0.55rem; border-radius: 50%; background: var(--gold); box-shadow: 0 0 6px var(--gold); }

/* ------------------------------------------------------------ Kämpfe sichtbar */
#text p.anzeichen { position: relative; animation: auftauchen 0.9s ease both, anzeichen 1.6s ease-in-out 0.9s 3; }
@keyframes anzeichen { 50% { border-left-color: #e0533f; box-shadow: -10px 0 18px -10px rgba(224, 83, 63, 0.7); } }
#text p.anzeichen.erkannt::after {
  content: "erkannt"; position: absolute; top: -0.9rem; left: 0.9rem; font-family: "Cormorant Garamond", serif;
  font-size: 0.72rem; letter-spacing: 0.15em; text-transform: uppercase; color: var(--gold);
}
body.treffer #vignette { animation: treffer 0.9s ease; }
@keyframes treffer { 0% { box-shadow: inset 0 0 0 0 transparent; } 15% { box-shadow: inset 0 0 22vmin 8vmin rgba(170, 20, 20, 0.6); } }
body.heilung #vignette { animation: heilung 0.9s ease; }
@keyframes heilung { 20% { box-shadow: inset 0 0 18vmin 4vmin rgba(200, 160, 90, 0.25); } }
#ueberblende { position: fixed; inset: 0; z-index: 40; background: #000; display: grid; place-items: center; opacity: 0; pointer-events: none; }
#ueberblende p { font-family: "Cormorant Garamond", serif; font-style: italic; letter-spacing: 0.3em; color: #b8ad9c; font-size: 1.3rem; opacity: 0; }
#ueberblende.an { animation: ueberblende 3.4s ease both; }
#ueberblende.an p { animation: ueberblende-text 3.4s ease both; }
@keyframes ueberblende { 0% { opacity: 0; } 25% { opacity: 1; } 70% { opacity: 1; } 100% { opacity: 0; } }
@keyframes ueberblende-text { 0%, 30% { opacity: 0; } 50% { opacity: 1; } 75% { opacity: 1; } 100% { opacity: 0; } }

/* ------------------------------------------------------------ Orte und Kapitel */
#text .ortskarte {
  display: flex; align-items: center; justify-content: center; gap: 0.8rem; margin: 2.6rem 0 1.4rem;
  font-family: "Cormorant Garamond", serif; letter-spacing: 0.28em; text-transform: uppercase; font-size: 0.95rem; color: var(--gold);
  animation: auftauchen 1.2s ease both;
}
#text .ortskarte::before, #text .ortskarte::after { content: ""; flex: 1; max-width: 6rem; border-top: 1px solid var(--linie); }
#text .ortskarte .zier { font-size: 0.7rem; color: var(--blass); }
#text p.titel { font-size: 1.6rem; padding: 1.4rem 0; border-top: 1px solid var(--linie); border-bottom: 1px solid var(--linie); }
#text p.chronik { font-size: 1rem; color: #c4baa9; padding-left: 1rem; border-left: 1px solid var(--linie); margin-bottom: 0.6em; }
#text p.chronik.nachwirkt::after { content: "  · wirkt nach"; font-style: italic; color: var(--blass); font-size: 0.85em; }
body[data-ort="traum"], body[data-ort="werkstatt"] { --tint: rgba(200, 190, 160, 0.12); }
body[data-ort="kanal"], body[data-ort="kanal_schwein"], body[data-ort="unterstadt"] { --tint: rgba(70, 90, 80, 0.16); }
body[data-ort="grab_oedon"], body[data-ort="graeber"] { --tint: rgba(110, 50, 40, 0.16); }

/* ------------------------------------------------------------ Notizbuch als Buch */
#notizbuch .reiter { display: flex; gap: 0.3rem; border-bottom: 1px solid var(--linie); margin-bottom: 0.6rem; flex-wrap: wrap; }
#notizbuch .reiter button { border: 0; border-bottom: 2px solid transparent; padding: 0.35rem 0.7rem; font-size: 0.95rem; color: var(--blass); }
#notizbuch .reiter button[aria-selected="true"] { color: var(--papier); border-bottom-color: var(--gold); }
#notizen article.neu h3::after, #notizen li.neu::after { content: " · neu"; font-family: "Cormorant Garamond", serif; font-size: 0.8rem; color: var(--gold); letter-spacing: 0.08em; }
#notizen p + p { margin-top: 0.4rem; }
#notizen .fragen { margin: 0; padding-left: 1.1rem; }
#notizen .fragen li { margin-bottom: 0.45rem; color: #bdb3a3; font-style: italic; }
@media (prefers-reduced-motion: reduce) { #text p.anzeichen, #ueberblende.an, #ueberblende.an p, #leiste .wert.leuchtet svg { animation: none; } }

/* Gelesen (Wunsch des Nutzers 2026-11-06): schon einmal gesehene Absätze und getroffene Entscheidungen grün. */
#text p.gelesen:not(.titel):not(.zwischentitel) { color: #9fc8a4; }
#text p.gelesen.alt { opacity: 0.72; }
#wahl .wahlzeile > button.gelesen { color: #9fc8a4; border-color: rgba(127, 174, 134, 0.5); }
#knopf-zurueck:disabled { opacity: 0.35; cursor: default; }

/* Kommentare an Claude (Wunsch des Nutzers 2026-11-06): Sprechblasen genau an der Stelle, mit Claudes Antworten. */
.kommentar { margin: -0.5rem 0 1.1rem; padding: 0.45rem 0.8rem; border-left: 3px solid var(--gold); background: rgba(179, 150, 98, 0.07); font-family: "EB Garamond", serif; font-size: 0.92rem; }
.kommentar p { margin: 0.2rem 0; }
.kommentar .wer { font-variant: small-caps; letter-spacing: 0.04em; color: var(--gold); }
.kommentar .claude { color: #a9bfd8; }
.kommentar .claude .wer { color: #a9bfd8; }
.kommentar .offen { cursor: pointer; }
#wahl .kommentar { margin: -0.2rem 0 0.4rem; }

/* Block „Claude erklärt“ und Bewertungen an Entscheidungen (Wunsch des Nutzers 2026-11-06), nur im Modus Bearbeiten. */
.erklaerung { margin-top: 0.8rem; padding: 0.6rem 0.9rem; border: 1px dashed rgba(169, 191, 216, 0.45); border-radius: 4px; font-size: 0.9rem; color: var(--blass); }
.erklaerung .erkl-kopf { margin: 0 0 0.4rem; font-variant: small-caps; letter-spacing: 0.05em; color: #a9bfd8; }
.erklaerung .erkl-text { margin: 0.5rem 0 0.15rem; color: var(--text, #d8d0c0); }
.erklaerung ul { margin: 0; padding-left: 1.1rem; }
.erklaerung li { margin: 0.1rem 0; }
.erklaerung li b { font-weight: 600; color: #a9bfd8; }
.erklaerung li.fehlt { opacity: 0.65; font-style: italic; }
body.bearbeiten #wahl button[data-bewertung="gut"]::after { content: "  👍"; }
body.bearbeiten #wahl button[data-bewertung="schlecht"]::after { content: "  👎"; }
